from pathlib import Path
import re

p=Path('index.html')
s=p.read_text(encoding='utf-8')

def rep(old,new,count=1):
    global s
    assert old in s, f'missing pattern: {old[:120]}'
    s=s.replace(old,new,count)

def sub(pattern,repl,count=1):
    global s
    ns,n=re.subn(pattern,repl,s,count=count,flags=re.S)
    assert n==count, f'pattern count {n} != {count}: {pattern[:120]}'
    s=ns

# Version/schema + local telemetry key.
rep('const APP_VERSION="4.1.0";\nconst DATA_VERSION=5;', 'const APP_VERSION="4.2.0";\nconst DATA_VERSION=6;')
rep('const COLLAPSE_KEY="doctrin-todo-collapsed-v1";', 'const COLLAPSE_KEY="doctrin-todo-collapsed-v1";\nconst FRICTION_KEY="doctrin-todo-friction-v1";')
rep('const VERSION_HISTORY=[\n {version:"4.1.0"', 'const VERSION_HISTORY=[\n {version:"4.2.0",date:"2026-08-16",text:"Development jobs from backlog plus local friction monitoring for repeated/no-op actions, undo/toggle loops, edit churn, navigation bounce, failed searches and sync trouble."},\n {version:"4.1.0"')

# Nav + visual language.
rep('    <button data-view="history"><span>Backlog & historik</span><span class="count" id="cBacklog">0</span></button>', '    <button data-view="history"><span>Backlog & historik</span><span class="count" id="cBacklog">0</span></button>\n    <button data-view="friction"><span>Friktion</span><span class="count" id="cFriction">0</span></button>')
rep('.selftest{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;padding:24px;background:#111;color:#ddd;min-height:100vh}', '.devjob{border-top:1px solid #ece9e2;padding:10px 0}.devjob:first-child{border-top:0}.devjob-actions,.friction-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:7px}.devjob-actions button,.friction-actions button{border:1px solid var(--line);background:#faf9f6;border-radius:7px;padding:5px 8px;font-size:11px}.friction-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin:12px 0 18px}.friction-stat{background:#faf9f6;border:1px solid var(--line);border-radius:10px;padding:10px}.friction-stat strong{display:block;font-size:20px}.friction-signal{border-top:1px solid #ece9e2;padding:12px 0}.friction-signal:first-of-type{border-top:0}.friction-score{display:inline-block;font-size:10px;font-weight:750;padding:2px 6px;border-radius:99px;background:var(--danger-soft);color:var(--danger);margin-left:6px}.monitor-row{display:flex;gap:10px;align-items:center;justify-content:space-between;background:#faf9f6;border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin-bottom:12px}.monitor-row label{display:flex;gap:7px;align-items:center;font-size:12px;font-weight:700}.privacy-note{font-size:11px;color:var(--muted);line-height:1.45}.selftest{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;padding:24px;background:#111;color:#ddd;min-height:100vh}')
