# State/data models.
rep('const state={tasks:[],backlog:[],updatedAt:new Date().toISOString(),view:"upcoming",query:"",undoStack:[],selectedId:null,inlineEditId:null,inlineFocus:"title",editingId:null,newFlags:{next:false,followup:false,some:false},collapsed:new Set()};', 'const state={tasks:[],backlog:[],devJobs:[],updatedAt:new Date().toISOString(),view:"upcoming",query:"",undoStack:[],selectedId:null,inlineEditId:null,inlineFocus:"title",editingId:null,newFlags:{next:false,followup:false,some:false},collapsed:new Set()};\nlet friction={enabled:true,events:[],signals:[],dismissed:0,lastSignalAt:{}};')
rep('function seedBacklog(){return DEFAULT_BACKLOG.map(normalizeBacklogItem)}', '''function seedBacklog(){return DEFAULT_BACKLOG.map(normalizeBacklogItem)}
function normalizeDevJob(x){return{id:x.id||uid(),createdAt:x.createdAt||new Date().toISOString(),updatedAt:x.updatedAt||x.createdAt||new Date().toISOString(),status:["ready","handed-off","done","failed"].includes(x.status)?x.status:"ready",backlogIds:Array.isArray(x.backlogIds)?x.backlogIds.map(String):[],prompt:String(x.prompt||""),note:String(x.note||"")}}
function defaultFriction(){return{enabled:true,events:[],signals:[],dismissed:0,lastSignalAt:{}}}
function normalizeFriction(x){const f=defaultFriction();if(!x||typeof x!=="object")return f;f.enabled=x.enabled!==false;f.events=Array.isArray(x.events)?x.events.slice(-250):[];f.signals=Array.isArray(x.signals)?x.signals.slice(0,80):[];f.dismissed=Number(x.dismissed)||0;f.lastSignalAt=x.lastSignalAt&&typeof x.lastSignalAt==="object"?x.lastSignalAt:{};return f}
function loadFriction(){try{friction=normalizeFriction(JSON.parse(localStorage.getItem(FRICTION_KEY)||"null"))}catch{friction=defaultFriction()}}
function saveFriction(){localStorage.setItem(FRICTION_KEY,JSON.stringify(friction))}
function cleanTarget(v){return String(v||"").replace(/[^a-zA-Z0-9_:\-.]/g,"_").slice(0,120)}
function tinyHash(v){let h=2166136261;for(const c of String(v||"")){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return(h>>>0).toString(36)}
function interactionFingerprint(){return hashData()+"|"+state.view+"|"+state.query+"|"+(state.inlineEditId||"")+"|"+[...state.collapsed].sort().join(",")}
function recentEvents(type,ms,target=null){const since=Date.now()-ms;return friction.events.filter(e=>e.ts>=since&&(!type||e.type===type)&&(target===null||e.target===target))}
function emitFrictionSignal(kind,target,title,description,score){const key=kind+"|"+target,now=Date.now(),last=Number(friction.lastSignalAt[key]||0);if(now-last<10*60*1000)return null;friction.lastSignalAt[key]=now;const sig={id:uid(),kind,target,title,description,score,detectedAt:new Date(now).toISOString(),status:"open"};friction.signals.unshift(sig);friction.signals=friction.signals.slice(0,80);saveFriction();if(!TEST_MODE)notice("Friktion upptäckt · "+title);return sig}
function detectFriction(){if(!friction.enabled)return;const last=friction.events[friction.events.length-1];if(!last)return;const noops=recentEvents("click",20000,last.target).filter(e=>e.meta?.changed===false);if(last.type==="click"&&last.meta?.changed===false&&noops.length>=3)emitFrictionSignal("repeated-noop",last.target,"Upprepade klick utan resultat",`${noops.length} klick på samma kontroll inom 20 sekunder utan observerbar state-förändring.`,4);const undos=recentEvents("undo",120000);if(undos.length>=3)emitFrictionSignal("undo-burst","global","Många Undo i följd",`${undos.length} Undo inom två minuter.`,5);if(last.type==="toggle"){const toggles=recentEvents("toggle",180000,last.target);if(toggles.length>=4)emitFrictionSignal("toggle-loop",last.target,"Tagg eller status växlas fram och tillbaka",`${toggles.length} växlingar på samma objekt inom tre minuter.`,4)}if(last.type==="edit"){const edits=recentEvents("edit",300000,last.target);if(edits.length>=4)emitFrictionSignal("edit-churn",last.target,"Samma todo redigeras upprepade gånger",`${edits.length} redigeringar av samma todo inom fem minuter.`,3)}if(last.type==="nav"){const nav=recentEvents("nav",120000),u=new Set(nav.map(e=>e.target));if(nav.length>=6&&u.size<=3)emitFrictionSignal("nav-bounce","views","Du hoppar fram och tillbaka mellan vyer",`${nav.length} vybyten mellan ${u.size} vyer inom två minuter.`,3)}if(last.type==="search"&&last.meta?.results===0){const miss=recentEvents("search",90000,last.target).filter(e=>e.meta?.results===0);if(miss.length>=3)emitFrictionSignal("search-miss",last.target,"Samma sökning ger ingen träff",`${miss.length} sökförsök utan resultat inom 90 sekunder.`,3)}if(last.type==="sync_error"){const errs=recentEvents("sync_error",600000);if(errs.length>=2)emitFrictionSignal("sync-trouble","dropbox","Återkommande synkproblem",`${errs.length} synkfel inom tio minuter.`,5)}if(last.type==="rollback"){const rolls=recentEvents("rollback",600000);if(rolls.length>=2)emitFrictionSignal("rollback-loop","global","Flera rollback på kort tid",`${rolls.length} rollback inom tio minuter.`,5)}}
function recordFrictionEvent(type,target="",meta={}){if(TEST_MODE||!friction.enabled)return;friction.events.push({id:uid(),ts:Date.now(),type,target:cleanTarget(target),meta:{...meta}});friction.events=friction.events.slice(-250);detectFriction();saveFriction()}
function recordFrictionEventForTest(type,target="",meta={}){friction.events.push({id:uid(),ts:Date.now(),type,target:cleanTarget(target),meta:{...meta}});friction.events=friction.events.slice(-250);detectFriction();saveFriction()}
''')

# Persist dev jobs with user data; friction remains local telemetry.
rep('function hashData(tasks=state.tasks,backlog=state.backlog){return JSON.stringify({tasks:tasks.map(t=>[t.id,t.title,t.notes,t.dueDate,t.completed,t.completedAt,t.cleared,t.path,t.tags]),backlog:backlog.map(b=>[b.id,b.type,b.title,b.description,b.selected,b.comment,b.status])})}', 'function hashData(tasks=state.tasks,backlog=state.backlog,devJobs=state.devJobs){return JSON.stringify({tasks:tasks.map(t=>[t.id,t.title,t.notes,t.dueDate,t.completed,t.completedAt,t.cleared,t.path,t.tags]),backlog:backlog.map(b=>[b.id,b.type,b.title,b.description,b.selected,b.comment,b.status]),devJobs:devJobs.map(j=>[j.id,j.status,j.backlogIds,j.prompt,j.note])})}')
sub(r'function load\(\)\{.*?\}\nfunction saveLocal\(touch=true\)\{.*?\}', '''function load(){try{const obj=JSON.parse(localStorage.getItem(STORAGE_KEY)||"null");if(obj&&Array.isArray(obj.tasks)){state.tasks=obj.tasks.map(normalizeTask);state.backlog=Array.isArray(obj.backlog)?obj.backlog.map(normalizeBacklogItem):seedBacklog();state.devJobs=Array.isArray(obj.devJobs)?obj.devJobs.map(normalizeDevJob):[];state.updatedAt=obj.updatedAt||new Date().toISOString()}else{state.tasks=[];state.backlog=seedBacklog();state.devJobs=[]}}catch{state.tasks=[];state.backlog=seedBacklog();state.devJobs=[]}loadCollapsed();loadFriction();saveLocal(false)}
function saveLocal(touch=true){if(touch)state.updatedAt=new Date().toISOString();localStorage.setItem(STORAGE_KEY,JSON.stringify({version:DATA_VERSION,appVersion:APP_VERSION,updatedAt:state.updatedAt,tasks:state.tasks,backlog:state.backlog,devJobs:state.devJobs}))}''')
rep('function createSnapshot(reason){if(!state.tasks.length&&!state.backlog.length)return;const a=snapshots(),fingerprint=hashData();if(a[0]?.fingerprint===fingerprint)return;a.unshift({id:uid(),createdAt:new Date().toISOString(),reason,version:APP_VERSION,fingerprint,tasks:JSON.parse(JSON.stringify(state.tasks)),backlog:JSON.parse(JSON.stringify(state.backlog))});setSnapshots(a)}', 'function createSnapshot(reason){if(!state.tasks.length&&!state.backlog.length&&!state.devJobs.length)return;const a=snapshots(),fingerprint=hashData();if(a[0]?.fingerprint===fingerprint)return;a.unshift({id:uid(),createdAt:new Date().toISOString(),reason,version:APP_VERSION,fingerprint,tasks:JSON.parse(JSON.stringify(state.tasks)),backlog:JSON.parse(JSON.stringify(state.backlog)),devJobs:JSON.parse(JSON.stringify(state.devJobs))});setSnapshots(a)}')
rep('function pushUndo(label){state.undoStack.push({label,tasks:JSON.parse(JSON.stringify(state.tasks)),backlog:JSON.parse(JSON.stringify(state.backlog))});if(state.undoStack.length>50)state.undoStack.shift();createSnapshot("Before: "+label)}', 'function pushUndo(label){state.undoStack.push({label,tasks:JSON.parse(JSON.stringify(state.tasks)),backlog:JSON.parse(JSON.stringify(state.backlog)),devJobs:JSON.parse(JSON.stringify(state.devJobs))});if(state.undoStack.length>50)state.undoStack.shift();createSnapshot("Before: "+label)}')
rep('function undo(){const prev=state.undoStack.pop();if(!prev){notice("Inget att ångra");return}createSnapshot("Before undo");state.tasks=(prev.tasks||[]).map(normalizeTask);state.backlog=(prev.backlog||state.backlog).map(normalizeBacklogItem);save();render();notice("Ångrade: "+prev.label)}', 'function undo(){const prev=state.undoStack.pop();if(!prev){notice("Inget att ångra");return}recordFrictionEvent("undo","global",{label:prev.label});createSnapshot("Before undo");state.tasks=(prev.tasks||[]).map(normalizeTask);state.backlog=(prev.backlog||state.backlog).map(normalizeBacklogItem);state.devJobs=(prev.devJobs||state.devJobs).map(normalizeDevJob);save();render();notice("Ångrade: "+prev.label)}')
rep('function restoreSnapshot(id){const snap=snapshots().find(s=>s.id===id);if(!snap)return;createSnapshot("Before rollback");state.tasks=(snap.tasks||[]).map(normalizeTask);if(Array.isArray(snap.backlog))state.backlog=snap.backlog.map(normalizeBacklogItem);save();render();notice("Rollback genomförd")}', 'function restoreSnapshot(id){const snap=snapshots().find(s=>s.id===id);if(!snap)return;recordFrictionEvent("rollback","snapshot",{});createSnapshot("Before rollback");state.tasks=(snap.tasks||[]).map(normalizeTask);if(Array.isArray(snap.backlog))state.backlog=snap.backlog.map(normalizeBacklogItem);if(Array.isArray(snap.devJobs))state.devJobs=snap.devJobs.map(normalizeDevJob);save();render();notice("Rollback genomförd")}')

# Development jobs.
rep('function generatePromptText(){', '''function developmentPrompt(items){let s="Implementera följande ändringar i repository stravus/todo. Arbeta på feature branch och skapa en reviewbar PR; skriv aldrig privata todo-data i repositoryt.\\n\\n";items.forEach((b,i)=>{s+=`${i+1}. [${b.type==="bug"?"BUG":"FÖRBÄTTRING"}] ${b.title}\\n`;if(b.description)s+=`   Beskrivning: ${b.description}\\n`;if(b.comment)s+=`   Kommentar: ${b.comment}\\n`;s+="\\n"});s+="Krav: behåll data-/Dropbox-kompatibilitet, uppdatera versionshistorik och testlogg, kör syntax-, funktions-, migration- och riktig browser-regression. Merge/publicera inte om tester fallerar.";return s}
function createDevJob(){const items=state.backlog.filter(b=>b.selected&&b.status!=="done");if(!items.length){notice("Markera minst en backlog-post");return null}pushUndo("create development job");const job=normalizeDevJob({backlogIds:items.map(b=>b.id),prompt:developmentPrompt(items),status:"ready"});state.devJobs.unshift(job);save();render();notice("Development job skapat");return job}
async function copyDevJob(id){const j=state.devJobs.find(x=>x.id===id);if(!j)return;try{await navigator.clipboard.writeText(j.prompt);notice("Development prompt kopierad")}catch{notice("Kunde inte kopiera prompt")}}
function handoffDevJob(id){const j=state.devJobs.find(x=>x.id===id);if(!j)return;const title=`Todo development job ${APP_VERSION} · ${j.backlogIds.length} poster`,body=j.prompt+`\\n\\nDevelopment job ID: ${j.id}`;j.status="handed-off";j.updatedAt=new Date().toISOString();save();window.open(`https://github.com/stravus/todo/issues/new?title=${encodeURIComponent(title)}&body=${encodeURIComponent(body)}`,"_blank","noopener");render()}
function setDevJobStatus(id,status){const j=state.devJobs.find(x=>x.id===id);if(!j)return;j.status=["ready","handed-off","done","failed"].includes(status)?status:j.status;j.updatedAt=new Date().toISOString();save();render()}
function devJobsHtml(){if(!state.devJobs.length)return`<div class="item-copy">Inga development jobs ännu.</div>`;return state.devJobs.slice(0,10).map(j=>`<div class="devjob" data-devjob="${esc(j.id)}"><div class="item-title">${esc(new Intl.DateTimeFormat("sv-SE",{dateStyle:"short",timeStyle:"short"}).format(new Date(j.createdAt)))} <span class="pill ${j.status==="done"?"done":""}">${esc(j.status)}</span></div><div class="item-copy">${j.backlogIds.length} backlog-poster · job ${esc(j.id.slice(0,8))}</div><div class="devjob-actions"><button data-jcopy="${esc(j.id)}">Kopiera prompt</button><button data-jhandoff="${esc(j.id)}">Öppna GitHub-uppdrag</button><select data-jstatus="${esc(j.id)}"><option value="ready" ${j.status==="ready"?"selected":""}>ready</option><option value="handed-off" ${j.status==="handed-off"?"selected":""}>handed-off</option><option value="done" ${j.status==="done"?"selected":""}>done</option><option value="failed" ${j.status==="failed"?"selected":""}>failed</option></select></div></div>`).join("")}
function generatePromptText(){''')
