# Backlog UI: add job creation + recent jobs.
sub(r'function backlogHtml\(\)\{(.*?)<div class="prompt-toolbar"><button class="btn primary" id="generatePromptBtn">Generera prompt</button><button class="btn" id="copyPromptBtn">Kopiera prompt</button></div><textarea class="prompt-box" id="promptBox" placeholder="Markerade backlog-poster hamnar här…"></textarea></section>`\}', r'''function backlogHtml(){\1<div class="prompt-toolbar"><button class="btn primary" id="createDevJobBtn">Implementera markerade</button><button class="btn" id="generatePromptBtn">Generera prompt</button><button class="btn" id="copyPromptBtn">Kopiera prompt</button></div><div class="item-copy">Implementera markerade skapar ett synkat development job. GitHub-handoff öppnar ett förifyllt uppdrag utan att lagra GitHub/OpenAI-hemligheter i appen.</div><textarea class="prompt-box" id="promptBox" placeholder="Markerade backlog-poster hamnar här…"></textarea><h3>Development jobs</h3>${devJobsHtml()}</section>`}''')

# Friction dashboard + bug conversion.
rep('function historyHtml(){', '''function frictionOpen(){return friction.signals.filter(x=>x.status==="open")}
function frictionStats(){const since=Date.now()-7*86400000,ev=friction.events.filter(e=>e.ts>=since);return{events:ev.length,undo:ev.filter(e=>e.type==="undo").length,noops:ev.filter(e=>e.type==="click"&&e.meta?.changed===false).length,signals:frictionOpen().length}}
function frictionHtml(){const st=frictionStats(),signals=friction.signals.filter(x=>x.status!=="dismissed");return`<div data-friction-ui><section class="panel"><div class="monitor-row"><label><input type="checkbox" id="frictionEnabled" ${friction.enabled?"checked":""}> Friction monitor aktiv</label><button class="btn" id="clearFrictionEvents">Rensa eventlogg</button></div><div class="privacy-note">Eventloggen lagras endast lokalt på den här enheten och innehåller action, tekniskt mål-ID, tid och enkel before/after-information — inte todo-texter. Buggar du skapar här blir vanlig backlog och synkas till Dropbox.</div><div class="friction-grid"><div class="friction-stat"><strong>${st.signals}</strong><span>öppna signaler</span></div><div class="friction-stat"><strong>${st.undo}</strong><span>Undo · 7 dagar</span></div><div class="friction-stat"><strong>${st.noops}</strong><span>no-op klick · 7 dagar</span></div><div class="friction-stat"><strong>${st.events}</strong><span>events · 7 dagar</span></div></div><h2>Upptäckta mönster</h2>${signals.length?signals.map(x=>`<div class="friction-signal" data-signal="${esc(x.id)}"><div class="item-title">${esc(x.title)}<span class="friction-score">score ${x.score}</span>${x.status==="backlog"?`<span class="pill done">bug skapad</span>`:""}</div><div class="item-copy">${esc(x.description)} · ${esc(new Intl.DateTimeFormat("sv-SE",{dateStyle:"short",timeStyle:"short"}).format(new Date(x.detectedAt)))}</div>${x.status==="open"?`<div class="friction-actions"><button data-signalbug="${esc(x.id)}">Skapa bug</button><button data-signaldismiss="${esc(x.id)}">Ignorera</button></div>`:""}</div>`).join(""):`<div class="empty">Inga friktionssignaler ännu.</div>`}</section></div>`}
function signalToBug(id){const x=friction.signals.find(s=>s.id===id);if(!x||x.status!=="open")return;state.backlog.unshift(normalizeBacklogItem({type:"bug",title:`Friktion: ${x.title}`,description:`Automatiskt upptäckt ${new Intl.DateTimeFormat("sv-SE",{dateStyle:"short",timeStyle:"short"}).format(new Date(x.detectedAt))}. ${x.description} Teknisk signal: ${x.kind}; mål: ${x.target}.`}));x.status="backlog";saveFriction();save();render();notice("Bug skapad i backlog")}
function dismissSignal(id){const x=friction.signals.find(s=>s.id===id);if(!x)return;x.status="dismissed";friction.dismissed++;saveFriction();render()}
function bindFriction(){document.getElementById("frictionEnabled")?.addEventListener("change",e=>{friction.enabled=e.target.checked;saveFriction();render()});document.getElementById("clearFrictionEvents")?.addEventListener("click",()=>{friction.events=[];saveFriction();render()});document.querySelectorAll("[data-signalbug]").forEach(b=>b.addEventListener("click",()=>signalToBug(b.dataset.signalbug)));document.querySelectorAll("[data-signaldismiss]").forEach(b=>b.addEventListener("click",()=>dismissSignal(b.dataset.signaldismiss)))}
function historyHtml(){''')

