rep('document.getElementById("addRow").style.display=["log","history"].includes(state.view)?"none":"grid";document.getElementById("search").style.display=state.view==="history"?"none":"block";', 'document.getElementById("addRow").style.display=["log","history","friction"].includes(state.view)?"none":"grid";document.getElementById("search").style.display=["history","friction"].includes(state.view)?"none":"block";')
