# Generic no-op click monitor + nav/search events.
sub(r'function bind\(\)\{document\.querySelectorAll\("#nav button"\)\.forEach\(b=>b\.addEventListener\("click",\(\)=>\{state\.view=b\.dataset\.view;state\.inlineEditId=null;state\.selectedId=null;render\(\)\}\)\);document\.getElementById\("search"\)\.addEventListener\("input",e=>\{state\.query=e\.target\.value;render\(\)\}\);', '''function bind(){document.querySelectorAll("#nav button").forEach(b=>b.addEventListener("click",()=>{recordFrictionEvent("nav",b.dataset.view,{});state.view=b.dataset.view;state.inlineEditId=null;state.selectedId=null;render()}));document.getElementById("search").addEventListener("input",e=>{state.query=e.target.value;render();if(state.query.trim().length>=2)recordFrictionEvent("search","q:"+tinyHash(state.query.trim().toLowerCase()),{results:filtered().length,length:state.query.trim().length})});''')
# Append generic capture just before keydown binding at end of bind().
rep('document.getElementById("closeShortcuts").addEventListener("click",()=>document.getElementById("shortcutsModal").classList.remove("open"));document.addEventListener("keydown",handleKeyboard)}', '''document.getElementById("closeShortcuts").addEventListener("click",()=>document.getElementById("shortcutsModal").classList.remove("open"));document.addEventListener("click",e=>{if(TEST_MODE||!friction.enabled||e.target.closest("[data-friction-ui]"))return;const el=e.target.closest("button,[data-action],[data-collapse],.path-chip,.task-title");if(!el)return;const task=el.closest(".task"),key=el.dataset.action?`action:${el.dataset.action}:${task?.dataset.id||""}`:el.dataset.view?`view:${el.dataset.view}`:el.id?`id:${el.id}`:el.dataset.collapse?`collapse:${tinyHash(el.dataset.collapse)}`:`el:${el.className}`;const before=interactionFingerprint();setTimeout(()=>recordFrictionEvent("click",key,{changed:before!==interactionFingerprint()}),120)},true);document.addEventListener("keydown",handleKeyboard)}''')

# Synced schema: dev jobs; local friction deliberately excluded.
rep('function exportPayload(){return{app:"Doctrin Todo",version:DATA_VERSION,appVersion:APP_VERSION,exportedAt:new Date().toISOString(),updatedAt:state.updatedAt,tasks:state.tasks,backlog:state.backlog}}', 'function exportPayload(){return{app:"Doctrin Todo",version:DATA_VERSION,appVersion:APP_VERSION,exportedAt:new Date().toISOString(),updatedAt:state.updatedAt,tasks:state.tasks,backlog:state.backlog,devJobs:state.devJobs}}')
rep('function remotePayload(){return{app:"Doctrin Todo",version:DATA_VERSION,appVersion:APP_VERSION,updatedAt:state.updatedAt||new Date().toISOString(),tasks:state.tasks,backlog:state.backlog}}', 'function remotePayload(){return{app:"Doctrin Todo",version:DATA_VERSION,appVersion:APP_VERSION,updatedAt:state.updatedAt||new Date().toISOString(),tasks:state.tasks,backlog:state.backlog,devJobs:state.devJobs}}')
sub(r'function applyRemote\(data,rev\)\{.*?return !Array\.isArray\(data\.backlog\)\}', '''function applyRemote(data,rev){if(!data||!Array.isArray(data.tasks))throw new Error("Dropbox-filen har fel format");const remoteBacklog=Array.isArray(data.backlog)?data.backlog.map(normalizeBacklogItem):null,remoteJobs=Array.isArray(data.devJobs)?data.devJobs.map(normalizeDevJob):null;if((state.tasks.length||state.backlog.length||state.devJobs.length)&&hashData(state.tasks,state.backlog,state.devJobs)!==hashData(data.tasks.map(normalizeTask),remoteBacklog||state.backlog,remoteJobs||state.devJobs))createSnapshot("Before Dropbox pull");state.tasks=data.tasks.map(normalizeTask);if(remoteBacklog)state.backlog=remoteBacklog;else if(!state.backlog.length)state.backlog=seedBacklog();if(remoteJobs)state.devJobs=remoteJobs;state.updatedAt=data.updatedAt||new Date().toISOString();syncState.remoteRev=rev;storeRemoteRev();saveLocal(false);render();return !Array.isArray(data.backlog)||!Array.isArray(data.devJobs)}''')
rep('const remoteTasks=(remote.data.tasks||[]).map(normalizeTask),remoteBacklog=Array.isArray(remote.data.backlog)?remote.data.backlog.map(normalizeBacklogItem):state.backlog,localHash=hashData(),remoteHash=hashData(remoteTasks,remoteBacklog),', 'const remoteTasks=(remote.data.tasks||[]).map(normalizeTask),remoteBacklog=Array.isArray(remote.data.backlog)?remote.data.backlog.map(normalizeBacklogItem):state.backlog,remoteJobs=Array.isArray(remote.data.devJobs)?remote.data.devJobs.map(normalizeDevJob):state.devJobs,localHash=hashData(),remoteHash=hashData(remoteTasks,remoteBacklog,remoteJobs),')
rep('setSyncStatus("syncing","Sparar…","Skriver todos + backlog till Dropbox/todos.json.");', 'setSyncStatus("syncing","Sparar…","Skriver todos + backlog + development jobs till Dropbox/todos.json.");')

