rep('const original={[STORAGE_KEY]:localStorage.getItem(STORAGE_KEY),[SNAPSHOT_KEY]:localStorage.getItem(SNAPSHOT_KEY),[WEEK_KEY]:localStorage.getItem(WEEK_KEY),[COLLAPSE_KEY]:localStorage.getItem(COLLAPSE_KEY)};', 'const original={[STORAGE_KEY]:localStorage.getItem(STORAGE_KEY),[SNAPSHOT_KEY]:localStorage.getItem(SNAPSHOT_KEY),[WEEK_KEY]:localStorage.getItem(WEEK_KEY),[COLLAPSE_KEY]:localStorage.getItem(COLLAPSE_KEY),[FRICTION_KEY]:localStorage.getItem(FRICTION_KEY)};')
